```json
{
  "root_causes": [
    {
      "service": "profile",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {
          "kind": "metric",
          "sql": "SELECT metric, service_name, min(value) mn, max(value) mx, count(*) n FROM abnormal_metrics WHERE metric='k8s.deployment.available' AND service_name='profile' GROUP BY 1,2",
          "claim": "profile k8s.deployment.available stays at 0 for the whole abnormal window, versus 1 in normal."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n FROM abnormal_traces WHERE service_name='profile' GROUP BY 1,2,3",
          "claim": "profile emits no spans at all in the abnormal window; normal had 1163 GetProfiles server spans."
        },
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_span_kind, count(*) n, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) errs, round(quantile_cont(duration,0.5)/1e6,2) p50_ms FROM abnormal_traces WHERE service_name='frontend' AND span_name='profile.Profile/GetProfiles' GROUP BY 1,2",
          "claim": "All 1131 frontend calls to profile.Profile/GetProfiles error out in about 0.01 ms p50."
        },
        {
          "kind": "log",
          "sql": "SELECT message, count(*) n FROM abnormal_logs WHERE message LIKE '%hotel-reserv-profile%' GROUP BY 1 ORDER BY n DESC",
          "claim": "Kubelet BackOff events show profile container hotel-reserv-profile repeatedly restarting after failure."
        }
      ]
    },
    {
      "service": "reservation",
      "fault_kind": "container_memory_saturated",
      "evidence": [
        {
          "kind": "metric",
          "sql": "SELECT service_name, round(avg(CASE WHEN metric='k8s.pod.memory.rss' THEN value END)/1e6,1) rss_mb_abn FROM abnormal_metrics WHERE service_name='reservation' AND metric='k8s.pod.memory.rss' GROUP BY 1",
          "claim": "reservation pod RSS jumps to about 694 MB during the abnormal window, from about 13.5 MB in normal."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, round(quantile_cont(duration,0.95)/1e6,2) p95_ms FROM abnormal_traces WHERE span_name='reservation.Reservation/CheckAvailability' GROUP BY 1,2,3",
          "claim": "reservation CheckAvailability server p95 rises from about 1.7 ms to 2.5 ms, with no errors."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, round(quantile_cont(duration,0.95)/1e6,2) p95_ms FROM abnormal_traces WHERE service_name='frontend' AND span_name='reservation.Reservation/CheckAvailability' GROUP BY 1,2,3",
          "claim": "frontend's client calls to CheckAvailability show p95 rising from about 2.0 ms to 2.8 ms."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "profile",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, count(*) n, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) errs FROM abnormal_traces WHERE service_name='frontend' AND attr_http_response_status_code=500 GROUP BY 1",
          "claim": "Frontend HTTP /hotels (724) and /recommendations (407) return 500 for every request, matching the failed profile calls."
        }
      ]
    },
    {
      "from": "reservation",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, round(quantile_cont(duration,0.95)/1e6,2) p95_ms FROM abnormal_traces WHERE span_name='reservation.Reservation/CheckAvailability' GROUP BY 1,2,3",
          "claim": "Reservation server p95 and frontend client p95 for CheckAvailability both rise in the abnormal window, with no errors."
        }
      ]
    }
  ]
}
